ini_set('display_errors',0); error_reporting(E_ALL); require_once __DIR__ . '/config.php'; header('Content-Type: application/json; charset=utf-8');
function sb($m,$ep,$p=null){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>60]);if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));$b=curl_exec($ch);$h=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ['ok'=>$h>=200&&$h<300,'body'=>$b,'data'=>is_array($d)?$d:[]];}
try{$key=$_GET['key']??'';if(!defined('AFTER_HOURS_CRON_KEY')||!hash_equals(AFTER_HOURS_CRON_KEY,$key)){http_response_code(403);echo json_encode(['success'=>false,'error'=>'Invalid key']);exit;}
$r=sb('GET','municipal_owner_records?select=town,street_name,owner_name,total_tax,seller_signal_score,owner_signal_score&limit=5000');if(!$r['ok']){echo json_encode(['success'=>false,'details'=>$r['body']]);exit;}$groups=[];
foreach($r['data'] as $x){$town=$x['town']?:'Fairfield';$street=trim($x['street_name']??'');if(!$street)continue;$k=$town.'|'.$street;if(!isset($groups[$k]))$groups[$k]=['town'=>$town,'street'=>$street,'owners'=>0,'trust'=>0,'estate'=>0,'llc'=>0,'tax'=>0,'seller'=>0,'max'=>0];$g=&$groups[$k];$g['owners']++;$o=strtoupper($x['owner_name']??'');if(str_contains($o,'TRUST'))$g['trust']++;if(str_contains($o,'ESTATE'))$g['estate']++;if(str_contains($o,'LLC'))$g['llc']++;$tax=(float)($x['total_tax']??0);$seller=max((int)($x['seller_signal_score']??0),(int)($x['owner_signal_score']??0));$g['tax']+=$tax;$g['seller']+=$seller;$g['max']=max($g['max'],$seller);}
$top=[];$count=0;foreach($groups as $g){$avgTax=$g['owners']?round($g['tax']/$g['owners'],2):0;$avgSeller=$g['owners']?round($g['seller']/$g['owners'],2):0;$score=30;if($g['owners']>=10)$score+=10;if($g['owners']>=25)$score+=10;if($avgTax>=10000)$score+=10;if($avgTax>=15000)$score+=10;if($g['trust']>0)$score+=8;if($g['estate']>0)$score+=10;if($g['llc']>0)$score+=6;if($avgSeller>=60)$score+=10;if($g['max']>=80)$score+=10;$score=min(100,$score);$notes='Jessica street read: '.$g['owners'].' owners, avg tax $'.number_format($avgTax).', trusts '.$g['trust'].', estates '.$g['estate'].', LLCs '.$g['llc'].'.';$p=['town'=>$g['town'],'street_name'=>$g['street'],'owner_count'=>$g['owners'],'trust_count'=>$g['trust'],'estate_count'=>$g['estate'],'llc_count'=>$g['llc'],'avg_tax'=>$avgTax,'total_tax'=>$g['tax'],'avg_seller_signal_score'=>$avgSeller,'max_seller_signal_score'=>$g['max'],'street_score'=>$score,'research_status'=>'active','jessica_notes'=>$notes,'recommended_action'=>$score>=75?'Research top owners on this street first.':'Keep in research pool.','updated_at'=>date('c')];$e=sb('GET','street_intelligence?select=id&town=eq.'.rawurlencode($g['town']).'&street_name=eq.'.rawurlencode($g['street']).'&limit=1');if($e['ok']&&!empty($e['data']))sb('PATCH','street_intelligence?id=eq.'.rawurlencode($e['data'][0]['id']),$p);else{$p['created_at']=date('c');sb('POST','street_intelligence',[$p]);}$count++;$top[]=$p;}usort($top,fn($a,$b)=>$b['street_score']<=>$a['street_score']);echo json_encode(['success'=>true,'streets_built'=>$count,'top_streets'=>array_slice($top,0,25)],JSON_PRETTY_PRINT);}catch(Throwable $e){http_response_code(500);echo json_encode(['success'=>false,'error'=>$e->getMessage(),'line'=>$e->getLine()],JSON_PRETTY_PRINT);}
